INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30379$nota-0063$m30379$, $m30380$Training and Racing with a Power Meter.pdf$m30380$, $m30381$161$m30381$, $m30382$TABLE 7.3 Impact of Training Stress on Fatigue — TSS <150: Low, Recovery is generally complete by the following day. 150-300: Moderate, Some residual fatigue may be present the next day, but recovery is generally complete by the second day. 300-450: High, Some residual fatigue may be present even after 2 days. >450: Very high, Residual fatigue lasting for several days is likely.$m30382$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30383$nota-0063$m30383$, $m30384$nota-0062$m30384$, $m30385$pre-requisito$m30385$, $m30386$usa o TSS definido na nota-0062 como entrada da escala$m30386$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30387$nota-0086$m30387$, $m30388$Training and Racing with a Power Meter.pdf$m30388$, $m30389$226$m30389$, $m30390$TABLE 9.1 Adjusting ATL to Account for Age — Age <19: 2-4 days; 20-29: 4-7 days; 30-49: 6-8 days; 50-59: 7-10 days; 60-65: 9-12 days; 66-70+: 11-14 days.$m30390$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30391$nota-0086$m30391$, $m30392$nota-0084$m30392$, $m30393$pre-requisito$m30393$, $m30394$ajusta a constante de tempo padrão do ATL definida na nota-0084$m30394$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30395$nota-0090$m30395$, $m30396$Training and Racing with a Power Meter.pdf$m30396$, $m30397$229$m30397$, $m30398$We have found that most cyclists can increase their CTL at a rate of 3–7 TSS per day per week. When you increase your CTL at a rate greater than 7 TSS per day per week for more than 4 weeks in a row, then the level of intense weekly training could be too much and send you into an overreaching downward spiral.$m30398$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30399$nota-0090$m30399$, $m30400$Training and Racing with a Power Meter.pdf$m30400$, $m30401$229$m30401$, $m30402$It's fine to increase TSS at a rate of more than 7 per day for 1 week, and possibly even for 2 weeks, but longer periods can lead you into a chronically overreached state.$m30402$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30403$nota-0090$m30403$, $m30404$Training and Racing with a Power Meter.pdf$m30404$, $m30405$230$m30405$, $m30406$TABLE 9.2 CTL Ramp Rate as a Function of Training Load — inclui, por exemplo: Long-term (14-28 dias), 5+ anos de treino, CTL<100: 7-10 TSS/dia; CTL>100: 5-7 TSS/dia. Short-term (<14 dias), 5+ anos, CTL<100: 14-20 TSS/dia; CTL>100: 10-14 TSS/dia.$m30406$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30407$nota-0090$m30407$, $m30408$nota-0083$m30408$, $m30409$pre-requisito$m30409$, $m30410$usa o CTL definido na nota-0083$m30410$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30411$nota-0090$m30411$, $m30412$nota-0092$m30412$, $m30413$causal$m30413$, $m30414$ultrapassar a taxa segura de ramp rate por tempo prolongado é uma das causas do overreaching não funcional descrito na nota-0092$m30414$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30415$nota-0092$m30415$, $m30416$Training and Racing with a Power Meter.pdf$m30416$, $m30417$229$m30417$, $m30418$Failure to periodically come up for air by allowing TSB to rise toward, if not all the way to, neutrality may lead to problems. If ATL is greater than CTL for too long, you will reach a state of non-functional over-reaching, where you can train but no longer improve and in fact become more and more fatigued. Too much time in a non-functional over-reaching state could lead to overtraining syndrome, at which point you would need to take months or even a year off the bike to recover.$m30418$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30419$nota-0092$m30419$, $m30420$nota-0085$m30420$, $m30421$pre-requisito$m30421$, $m30422$usa o TSB (CTL-ATL) definido na nota-0085 como sinal de alerta$m30422$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30423$nota-0092$m30423$, $m30424$nota-0090$m30424$, $m30425$causal$m30425$, $m30426$ramp rate de CTL excessivo (nota-0090) é uma via comum para cair nesse estado de overreaching$m30426$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30427$nota-0096$m30427$, $m30428$Training and Racing with a Power Meter.pdf$m30428$, $m30429$268$m30429$, $m30430$Jill will ride her bike this week, but when she does, she will ride easy. And when she rides easy, she must ride really easy, keeping her watts under 62 percent of her FTP—no speeding over 14 mph on a flat road... During Week 4, Jill will limit her riding to less than 2 hours per day, with her rides during the week lasting only an hour and 15 minutes. A rest week means that you also rest completely on some days.$m30430$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30431$nota-0096$m30431$, $m30432$nota-0022$m30432$, $m30433$complementa$m30433$, $m30434$refina o teto de intensidade da semana de recuperação além do limite genérico da Zona 1 (Active Recovery, <55% FTP) definido no Capítulo 2, aplicado aqui como regra prática para a semana inteira$m30434$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30435$nota-0148$m30435$, $m30436$Training and Racing with a Power Meter.pdf$m30436$, $m30437$472$m30437$, $m30438$Overreached An acute state of fatigue and hence diminished performance resulting from a brief period of excessive training relative to what you normally perform. Although many times riders describe themselves as being 'overtrained,' in reality they have usually simply overreached and their performance will recover after just a few days of rest or reduced training.$m30438$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30439$nota-0148$m30439$, $m30440$Training and Racing with a Power Meter.pdf$m30440$, $m30441$472$m30441$, $m30442$Overtrained A chronic state of overreaching from which recovery takes a long period of time, usually over 30 days. Also called Overtraining Syndrome (OTS).$m30442$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30443$nota-0148$m30443$, $m30444$nota-0092$m30444$, $m30445$complementa$m30445$, $m30446$fornece o critério temporal exato para diferenciar overreaching não funcional (nota-0092) de overtraining syndrome propriamente dito$m30446$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30447$nota-0160$m30447$, $m30448$Manual treinamento.pdf$m30448$, $m30449$60$m30449$, $m30450$em intensidades elevadas, os músculos respiratórios podem consumir entre 10 e 15% do consumo total de oxigênio... Quando ocorre fadiga respiratória, mecanismos neurais aumentam a atividade simpática, reduzindo parcialmente o fluxo sanguíneo para os membros inferiores. Esse fenômeno é conhecido como metaborreflexo dos músculos respiratórios.$m30450$);
